package com.splitmate.repo; import com.splitmate.domain.Membership; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface MembershipRepository extends JpaRepository<Membership,Long>{List<Membership> findByUserId(Long userId); List<Membership> findByHouseholdId(Long householdId); Optional<Membership> findByHouseholdIdAndUserId(Long householdId,Long userId); boolean existsByHouseholdIdAndUserId(Long householdId,Long userId);}
